import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';

const Submissions = () => {
  const [submissions, setSubmissions] = useState([]);
  const [loading, setLoading] = useState(true);
  const { token } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    fetchSubmissions();
  }, []);

  const fetchSubmissions = async () => {
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/submissions/user`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSubmissions(response.data.submissions || []);
    } catch (error) {
      console.error('Error fetching submissions:', error);
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    if (status === 'accepted') {
      return { text: '✅ Accepted', style: styles.statusAccepted };
    }
    return { text: '❌ Wrong Answer', style: styles.statusFailed };
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div className="loading-spinner"></div>
        <p>Loading submissions...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* Navigation */}
      <nav style={styles.nav}>
        <div style={styles.navLeft}>
          <h1 style={styles.logo}>⚡ CodeArena</h1>
          <span style={styles.navSubtitle}>My Submissions</span>
        </div>
        <div style={styles.navRight}>
          <button onClick={() => navigate('/problems')} style={styles.navButton}>
            📚 Problems
          </button>
          <button onClick={() => navigate('/')} style={styles.navButton}>
            🏠 Dashboard
          </button>
        </div>
      </nav>

      {/* Header */}
      <div style={styles.header}>
        <h1 style={styles.title}>📊 My Submissions</h1>
        <p style={styles.subtitle}>Track your progress and coding journey</p>
      </div>

      {/* Stats Summary */}
      {submissions.length > 0 && (
        <div style={styles.statsBar}>
          <div style={styles.statItem}>
            <span style={styles.statLabel}>Total Submissions</span>
            <span style={styles.statValue}>{submissions.length}</span>
          </div>
          <div style={styles.statItem}>
            <span style={styles.statLabel}>Accepted</span>
            <span style={styles.statValue}>
              {submissions.filter(s => s.status === 'accepted').length}
            </span>
          </div>
          <div style={styles.statItem}>
            <span style={styles.statLabel}>Success Rate</span>
            <span style={styles.statValue}>
              {submissions.length > 0 
                ? Math.round((submissions.filter(s => s.status === 'accepted').length / submissions.length) * 100)
                : 0}%
            </span>
          </div>
        </div>
      )}

      {/* Submissions Table */}
      {submissions.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={styles.emptyIcon}>📝</div>
          <h3>No submissions yet</h3>
          <p>Start solving problems to see your submissions here</p>
          <button onClick={() => navigate('/problems')} style={styles.startButton}>
            Browse Problems
          </button>
        </div>
      ) : (
        <div style={styles.tableContainer}>
          <table style={styles.table}>
            <thead>
              <tr>
                <th style={styles.th}>Problem</th>
                <th style={styles.th}>Language</th>
                <th style={styles.th}>Score</th>
                <th style={styles.th}>Status</th>
                <th style={styles.th}>Date</th>
              </tr>
            </thead>
            <tbody>
              {submissions.map((sub) => {
                const status = getStatusBadge(sub.status);
                return (
                  <tr key={sub._id} style={styles.tr}>
                    <td style={styles.td}>
                      <span style={styles.problemTitle}>
                        {sub.problem?.title || 'Unknown Problem'}
                      </span>
                    </td>
                    <td style={styles.td}>
                      <span style={styles.languageBadge}>
                        {sub.language?.toUpperCase()}
                      </span>
                    </td>
                    <td style={styles.td}>
                      <span style={styles.scoreValue}>
                        {sub.score?.toFixed(1)}%
                      </span>
                    </td>
                    <td style={styles.td}>
                      <span style={status.style}>
                        {status.text}
                      </span>
                    </td>
                    <td style={styles.td}>
                      {new Date(sub.submittedAt).toLocaleDateString()}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f5f7fa'
  },
  nav: {
    background: 'white',
    padding: '15px 30px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)',
    position: 'sticky',
    top: 0,
    zIndex: 100
  },
  navLeft: {
    display: 'flex',
    alignItems: 'center',
    gap: '15px'
  },
  logo: {
    color: '#1a73e8',
    fontSize: '24px',
    margin: 0
  },
  navSubtitle: {
    color: '#666',
    fontSize: '16px'
  },
  navRight: {
    display: 'flex',
    gap: '10px'
  },
  navButton: {
    padding: '8px 16px',
    background: '#f0f2f5',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '14px'
  },
  loadingContainer: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh'
  },
  header: {
    padding: '30px 40px',
    background: 'white',
    margin: '20px 20px 0 20px',
    borderRadius: '12px 12px 0 0',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)'
  },
  title: {
    fontSize: '28px',
    marginBottom: '5px'
  },
  subtitle: {
    color: '#666',
    fontSize: '14px'
  },
  statsBar: {
    display: 'flex',
    gap: '30px',
    padding: '15px 20px',
    background: 'white',
    margin: '0 20px',
    borderBottom: '1px solid #e9ecef',
    flexWrap: 'wrap'
  },
  statItem: {
    display: 'flex',
    flexDirection: 'column'
  },
  statLabel: {
    fontSize: '12px',
    color: '#999',
    textTransform: 'uppercase'
  },
  statValue: {
    fontSize: '20px',
    fontWeight: 'bold',
    color: '#1a73e8'
  },
  tableContainer: {
    background: 'white',
